import React from 'react';
import { MarketInsight, AssetStatus, CompletionStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusColor = (status: AssetStatus) => {
  switch (status) {
    case '突破': return 'bg-white/80 text-green-600 border-green-200';
    case '看涨': return 'bg-white/80 text-blue-600 border-blue-200';
    case '看跌': return 'bg-white/80 text-red-600 border-red-200';
    case '关键位置': return 'bg-white/80 text-orange-600 border-orange-200';
    default: return 'bg-white/80 text-gray-500 border-gray-200';
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const status = insight.completionStatus;

  const getCardStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-50/40 border-emerald-100 shadow-sm';
      case '已失效': return 'bg-slate-100/40 border-slate-200 shadow-none opacity-80 grayscale-[0.3]';
      default: return 'bg-white border-gray-100 shadow-sm hover:shadow-md';
    }
  };

  const getTagStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-sky-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (status) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-[2rem] p-5 transition-all duration-300 flex flex-col h-full ${getCardStyle()}`}>
      {/* 顶部状态标记 */}
      <div className="absolute -top-2.5 left-5 flex gap-2">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider shadow-sm transition-transform active:scale-95 ${getTagStyle()}`}
          title="点击切换状态"
        >
          {getStatusIcon()}
          {status}
        </button>
      </div>

      <div className="flex justify-between items-start mb-3 gap-3 pt-1">
        <div className="flex-grow">
          <h3 className="text-xl font-black text-gray-900 leading-none mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1 font-bold">
            <Calendar className="w-3 h-3 opacity-70" />
            {date}
          </div>
        </div>
        <div className={`px-3 py-1 rounded-xl text-[10px] font-black border flex items-center justify-center shrink-0 min-w-[60px] ${getAssetStatusColor(insight.status)}`}>
          {insight.status}
        </div>
      </div>

      <div className="space-y-3 flex-grow">
        <div className={`p-3.5 rounded-2xl border transition-colors ${
          status === '已完成' ? 'bg-white/60 border-emerald-100/50' : status === '已失效' ? 'bg-white/40 border-slate-100/50' : 'bg-gray-50/50 border-gray-100'
        }`}>
          <p className={`text-[9px] font-black uppercase tracking-wider mb-1.5 ${
            status === '已完成' ? 'text-emerald-500/70' : status === '已失效' ? 'text-slate-400' : 'text-gray-400'
          }`}>核心观察</p>
          <p className={`text-xs leading-relaxed font-semibold line-clamp-3 ${status === '已失效' ? 'text-slate-500' : 'text-gray-700'}`}>
            {insight.focusPoints}
          </p>
        </div>

        {insight.keyLevel && (
          <div className={`flex items-center justify-between p-2.5 px-3.5 rounded-xl border border-dashed ${
            status === '已完成' ? 'bg-emerald-500/5 border-emerald-200/40' : status === '已失效' ? 'bg-slate-500/5 border-slate-200/40' : 'bg-sky-500/5 border-sky-200/40'
          }`}>
            <p className={`text-[9px] font-black uppercase tracking-wider ${
              status === '已完成' ? 'text-emerald-500' : status === '已失效' ? 'text-slate-500' : 'text-sky-500'
            }`}>关键点位</p>
            <p className={`text-sm font-black tracking-tight ${
              status === '已完成' ? 'text-emerald-600' : status === '已失效' ? 'text-slate-600' : 'text-sky-600'
            }`}>{insight.keyLevel}</p>
          </div>
        )}

        <div>
          <div className={`p-3.5 rounded-2xl border-l-4 ${
            status === '已完成' 
              ? 'bg-gray-900 border-emerald-500' 
              : status === '已失效'
              ? 'bg-gray-800 border-slate-500 opacity-80'
              : 'bg-gray-900 border-sky-500 shadow-md shadow-gray-100'
          }`}>
            <p className="text-[9px] font-black text-gray-500 uppercase tracking-wider mb-1">交易策略</p>
            <p className="text-xs text-gray-100 font-bold leading-relaxed line-clamp-2 italic">
              “{insight.strategy}”
            </p>
          </div>
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-gray-100/60 flex justify-end items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-lg transition-colors flex items-center gap-1.5 text-[10px] font-black"
        >
          <Edit2 className="w-3 h-3" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors flex items-center gap-1.5 text-[10px] font-black"
        >
          <Trash2 className="w-3 h-3" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive, Inbox } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('timeline');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 生成侧边栏的时间轴归档分组
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  // 根据当前筛选条件进行初步过滤
  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  // 分离活跃和已归档见解
  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus !== '已失效'),
      archivedItems: filteredInsights.filter(i => i.completionStatus === '已失效')
    };
  }, [filteredInsights]);

  // 对活跃见解进行分组
  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};

    activeItems.forEach(insight => {
      let label = "";
      if (sortMode === 'timeline') {
        const d = new Date(insight.updatedAt);
        label = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
      } else {
        label = insight.category;
      }

      if (!groups[label]) {
        groups[label] = [];
      }
      groups[label].push(insight);
    });

    const entries = Object.entries(groups);
    if (sortMode === 'category') {
      return entries.sort((a, b) => {
        return CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any);
      });
    }
    return entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { 
        ...i, 
        ...data, 
        updatedAt: data.updatedAt || i.updatedAt 
      } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col">
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-xl border-b border-gray-100 px-6 py-3">
        <div className="max-w-[1600px] mx-auto flex flex-col gap-3">
          <div className="flex items-center justify-between h-10">
            <div className="flex items-center gap-3">
              <div className="bg-gray-900 p-2 rounded-xl shadow-md">
                <LayoutGrid className="w-4 h-4 text-white" />
              </div>
              <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none">市场周刊</h1>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
                className="bg-red-500 text-white px-4 py-2 rounded-xl hover:bg-red-600 transition-all flex items-center gap-1.5 shadow-lg shadow-red-100 font-bold text-xs"
              >
                <Plus className="w-3.5 h-3.5" />
                <span>新记录</span>
              </button>
            </div>
          </div>

          <nav className="flex items-center gap-1 overflow-x-auto no-scrollbar pb-1">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-1.5 rounded-lg text-[11px] font-black transition-all whitespace-nowrap ${
                  activeCategory === cat 
                    ? 'bg-gray-900 text-white shadow-sm' 
                    : 'text-gray-400 hover:text-gray-900 hover:bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-6 py-8 w-full flex flex-col lg:flex-row gap-8">
        <aside className="lg:w-48 space-y-8 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-4 px-1">
              <Clock className="w-3.5 h-3.5 text-gray-400" />
              <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">时间轴归档</h3>
            </div>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-3 py-2.5 rounded-xl text-xs font-black transition-all flex items-center justify-between group ${
                  selectedMonth === null ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                }`}
              >
                <span className="flex items-center gap-2">
                  <Hash className={`w-3 h-3 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  全部时间
                </span>
                <span className={`text-[9px] px-1.5 py-0.5 rounded-full ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-3 py-2.5 rounded-xl text-xs font-black transition-all flex items-center justify-between group ${
                    selectedMonth === month ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Calendar className={`w-3 h-3 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[9px] px-1.5 py-0.5 rounded-full ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-8">
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight italic">
                每一天都有新的洞察。
              </h2>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex bg-gray-100/80 p-1 rounded-xl items-center">
                <button 
                  onClick={() => setSortMode('timeline')}
                  className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-[9px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <CalendarDays className="w-2.5 h-2.5" />
                  时间线
                </button>
                <button 
                  onClick={() => setSortMode('category')}
                  className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-[9px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <ListFilter className="w-2.5 h-2.5" />
                  按类别
                </button>
              </div>

              <div className="text-[10px] text-gray-400 font-black bg-white px-3 py-1.5 rounded-full border border-gray-100 shadow-sm">
                共计 <span className="text-gray-900">{filteredInsights.length}</span> 条见解
              </div>
            </div>
          </div>

          {/* 活跃见解区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-12">
              <div className="flex items-center gap-2 mb-2">
                <Inbox className="w-4 h-4 text-gray-900" />
                <h3 className="text-md font-black text-gray-900">活跃洞察</h3>
              </div>
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel} className="relative">
                  <div className="flex items-center gap-3 mb-6 sticky top-[130px] z-10 py-1.5 bg-[#fafafa]/80 backdrop-blur-sm">
                    <div className="h-px flex-grow bg-gray-200/50"></div>
                    <div className="flex items-center gap-2 px-4 py-1.5 bg-white rounded-full border border-gray-100 shadow-sm">
                      {sortMode === 'timeline' ? <Calendar className="w-3 h-3 text-red-500" /> : <Hash className="w-3 h-3 text-blue-500" />}
                      <span className="text-[10px] font-black text-gray-900 tracking-tight">{groupLabel}</span>
                    </div>
                    <div className="h-px flex-grow bg-gray-200/50"></div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : filteredInsights.length === 0 && (
            <div className="text-center py-32 bg-white rounded-[2.5rem] border border-gray-100 shadow-sm">
              <div className="max-w-xs mx-auto">
                <div className="w-12 h-12 bg-gray-50 rounded-2xl flex items-center justify-center mx-auto mb-4">
                  <Clock className="w-6 h-6 text-gray-200" />
                </div>
                <h3 className="text-md font-bold text-gray-900 mb-1">暂无匹配记录</h3>
                <p className="text-xs text-gray-400 mb-6 leading-relaxed">
                  在该筛选条件下未找到任何分析。尝试更换分类或查看其他月份。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-2 px-6 py-2.5 bg-gray-900 rounded-xl font-black text-xs text-white hover:bg-black transition-all shadow-lg"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}

          {/* 已归档见解区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-16 space-y-6">
              <div className="flex items-center justify-between border-t border-dashed border-gray-200 pt-12">
                <div className="flex items-center gap-2">
                  <div className="p-1.5 bg-gray-100 rounded-lg">
                    <Archive className="w-4 h-4 text-gray-400" />
                  </div>
                  <div>
                    <h3 className="text-md font-black text-gray-400">已归档历史</h3>
                    <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">已失效的市场分析</p>
                  </div>
                </div>
                <span className="text-[9px] font-black text-gray-300 bg-gray-50 px-2 py-0.5 rounded-full border border-gray-100">
                  {archivedItems.length} 条归档
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-8 bg-white">
        <div className="max-w-[1600px] mx-auto px-6 text-center">
          <p className="text-[9px] text-gray-300 font-bold uppercase tracking-[0.3em]">个人交易日记 system · 洞察记录与回溯</p>
        </div>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

export type AssetStatus = '看涨' | '看跌' | '震荡';
export type CompletionStatus = '进行中' | '已完成' | '已失效';
export type SortMode = 'timeline' | 'category';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  keyLevel?: string;
  updatedAt: number;
  completionStatus: CompletionStatus;
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
  sortMode: SortMode;
}

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle, TrendingUp, TrendingDown, Activity } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-white/80 text-red-600 border-red-200',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-white/80 text-green-600 border-green-200',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-white/80 text-blue-600 border-blue-200',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-white/80 text-gray-500 border-gray-200',
      icon: <Circle className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const status = insight.completionStatus;
  const { color, icon } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-50/40 border-emerald-100 shadow-sm';
      case '已失效': return 'bg-slate-100/40 border-slate-200 shadow-none opacity-80 grayscale-[0.3]';
      default: return 'bg-white border-gray-100 shadow-sm hover:shadow-md';
    }
  };

  const getTagStyle = () => {
    switch (status) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-sky-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (status) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-[2rem] p-5 transition-all duration-300 flex flex-col h-full ${getCardStyle()}`}>
      {/* 顶部状态标记 */}
      <div className="absolute -top-2.5 left-5 flex gap-2">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider shadow-sm transition-transform active:scale-95 ${getTagStyle()}`}
          title="点击切换状态"
        >
          {getStatusIcon()}
          {status}
        </button>
      </div>

      <div className="flex justify-between items-start mb-3 gap-3 pt-1">
        <div className="flex-grow">
          <h3 className="text-xl font-black text-gray-900 leading-none mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1 font-bold">
            <Calendar className="w-3 h-3 opacity-70" />
            {date}
          </div>
        </div>
        <div className={`px-2.5 py-1 rounded-xl text-[10px] font-black border flex items-center justify-center gap-1.5 shrink-0 min-w-[70px] ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="space-y-3 flex-grow">
        <div className={`p-3.5 rounded-2xl border transition-colors ${
          status === '已完成' ? 'bg-white/60 border-emerald-100/50' : status === '已失效' ? 'bg-white/40 border-slate-100/50' : 'bg-gray-50/50 border-gray-100'
        }`}>
          <p className={`text-[9px] font-black uppercase tracking-wider mb-1.5 ${
            status === '已完成' ? 'text-emerald-500/70' : status === '已失效' ? 'text-slate-400' : 'text-gray-400'
          }`}>核心观察</p>
          <p className={`text-xs leading-relaxed font-semibold line-clamp-3 ${status === '已失效' ? 'text-slate-500' : 'text-gray-700'}`}>
            {insight.focusPoints}
          </p>
        </div>

        {insight.keyLevel && (
          <div className={`flex items-center justify-between p-2.5 px-3.5 rounded-xl border border-dashed ${
            status === '已完成' ? 'bg-emerald-500/5 border-emerald-200/40' : status === '已失效' ? 'bg-slate-500/5 border-slate-200/40' : 'bg-sky-500/5 border-sky-200/40'
          }`}>
            <p className={`text-[9px] font-black uppercase tracking-wider ${
              status === '已完成' ? 'text-emerald-500' : status === '已失效' ? 'text-slate-500' : 'text-sky-500'
            }`}>关键点位</p>
            <p className={`text-sm font-black tracking-tight ${
              status === '已完成' ? 'text-emerald-600' : status === '已失效' ? 'text-slate-600' : 'text-sky-600'
            }`}>{insight.keyLevel}</p>
          </div>
        )}

        <div>
          <div className={`p-3.5 rounded-2xl border-l-4 ${
            status === '已完成' 
              ? 'bg-gray-900 border-emerald-500' 
              : status === '已失效'
              ? 'bg-gray-800 border-slate-500 opacity-80'
              : 'bg-gray-900 border-sky-500 shadow-md shadow-gray-100'
          }`}>
            <p className="text-[9px] font-black text-gray-500 uppercase tracking-wider mb-1">交易策略</p>
            <p className="text-xs text-gray-100 font-bold leading-relaxed line-clamp-2 italic">
              “{insight.strategy}”
            </p>
          </div>
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-gray-100/60 flex justify-end items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-lg transition-colors flex items-center gap-1.5 text-[10px] font-black"
        >
          <Edit2 className="w-3 h-3" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors flex items-center gap-1.5 text-[10px] font-black"
        >
          <Trash2 className="w-3 h-3" />
          删除
        </button>
      </div>
    </div>
  );
};

