import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive, Inbox, Search } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('timeline');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 生成侧边栏的时间轴归档分组
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  // 根据当前筛选条件进行初步过滤
  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  // 分离活跃和已归档见解
  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus !== '已失效'),
      archivedItems: filteredInsights.filter(i => i.completionStatus === '已失效')
    };
  }, [filteredInsights]);

  // 对活跃见解进行分组
  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};

    activeItems.forEach(insight => {
      let label = "";
      if (sortMode === 'timeline') {
        const d = new Date(insight.updatedAt);
        label = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
      } else {
        label = insight.category;
      }

      if (!groups[label]) {
        groups[label] = [];
      }
      groups[label].push(insight);
    });

    const entries = Object.entries(groups);
    if (sortMode === 'category') {
      return entries.sort((a, b) => {
        return CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any);
      });
    }
    return entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { 
        ...i, 
        ...data, 
        updatedAt: data.updatedAt || i.updatedAt 
      } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col">
      <header className="sticky top-0 z-40 bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-6 py-4">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between gap-6">
          {/* 左侧：Logo 和 标题 */}
          <div className="flex items-center gap-3.5 shrink-0 min-w-[200px]">
            <div className="bg-gray-900 p-2.5 rounded-2xl shadow-lg shadow-gray-200">
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none mb-0.5">市场周刊</h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Market Weekly</p>
            </div>
          </div>

          {/* 中间：居中的导航栏 */}
          <nav className="hidden md:flex items-center bg-gray-50/80 p-1.5 rounded-2xl border border-gray-100/50 gap-1.5 overflow-hidden">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-6 py-2 rounded-xl text-[13px] font-black transition-all whitespace-nowrap active:scale-95 ${
                  activeCategory === cat 
                    ? 'bg-white text-gray-900 shadow-sm border border-gray-100' 
                    : 'text-gray-400 hover:text-gray-900 hover:bg-white/50'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>

          {/* 右侧：操作按钮 */}
          <div className="flex items-center gap-3 shrink-0 min-w-[200px] justify-end">
            <button className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-xl transition-colors">
              <Search className="w-5 h-5" />
            </button>
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-5 py-2.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2 shadow-xl shadow-red-100 font-black text-sm active:scale-95"
            >
              <Plus className="w-4 h-4" />
              <span>新记录</span>
            </button>
          </div>
        </div>

        {/* 移动端导航（仅在大屏幕下隐藏） */}
        <div className="md:hidden mt-4 overflow-x-auto no-scrollbar">
          <nav className="flex items-center gap-1.5 pb-1">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-2 rounded-xl text-[12px] font-black transition-all whitespace-nowrap ${
                  activeCategory === cat 
                    ? 'bg-gray-900 text-white shadow-md' 
                    : 'text-gray-400 hover:text-gray-900 bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-6 py-10 w-full flex flex-col lg:flex-row gap-8">
        <aside className="lg:w-52 space-y-10 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-5 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest">时间轴归档</h3>
            </div>
            <div className="space-y-1.5">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-2xl text-xs font-black transition-all flex items-center justify-between group border ${
                  selectedMonth === null 
                    ? 'bg-white border-gray-200 shadow-sm text-gray-900' 
                    : 'bg-transparent border-transparent text-gray-400 hover:text-gray-600 hover:bg-gray-100/50'
                }`}
              >
                <span className="flex items-center gap-2.5">
                  <Hash className={`w-3.5 h-3.5 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-2xl text-xs font-black transition-all flex items-center justify-between group border ${
                    selectedMonth === month 
                      ? 'bg-white border-gray-200 shadow-sm text-gray-900' 
                      : 'bg-transparent border-transparent text-gray-400 hover:text-gray-600 hover:bg-gray-100/50'
                  }`}
                >
                  <span className="flex items-center gap-2.5">
                    <Calendar className={`w-3.5 h-3.5 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-10">
            <div className="space-y-1">
              <p className="text-[11px] font-black text-red-500 uppercase tracking-[0.2em]">Weekly Insights</p>
              <h2 className="text-3xl font-black text-gray-900 tracking-tight italic">
                每一天都有新的洞察。
              </h2>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex bg-gray-100/80 p-1.5 rounded-2xl items-center border border-gray-200/50">
                <button 
                  onClick={() => setSortMode('timeline')}
                  className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-[10px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <CalendarDays className="w-3 h-3" />
                  时间线
                </button>
                <button 
                  onClick={() => setSortMode('category')}
                  className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-[10px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <ListFilter className="w-3 h-3" />
                  按类别
                </button>
              </div>

              <div className="text-[11px] text-gray-500 font-black bg-white px-4 py-2 rounded-2xl border border-gray-100 shadow-sm">
                共计 <span className="text-gray-900">{filteredInsights.length}</span> 条见解
              </div>
            </div>
          </div>

          {/* 活跃见解区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-16">
              <div className="flex items-center gap-3 mb-2">
                <div className="w-8 h-8 bg-gray-900 rounded-xl flex items-center justify-center">
                  <Inbox className="w-4 h-4 text-white" />
                </div>
                <h3 className="text-lg font-black text-gray-900">活跃洞察</h3>
              </div>
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel} className="relative">
                  <div className="flex items-center gap-4 mb-8 sticky top-[110px] z-10 py-3 bg-[#fafafa]/80 backdrop-blur-sm">
                    <div className="flex items-center gap-2.5 px-5 py-2 bg-white rounded-2xl border border-gray-200 shadow-sm">
                      {sortMode === 'timeline' ? <Calendar className="w-4 h-4 text-red-500" /> : <Hash className="w-4 h-4 text-blue-500" />}
                      <span className="text-xs font-black text-gray-900 tracking-tight">{groupLabel}</span>
                    </div>
                    <div className="h-px flex-grow bg-gray-200/60"></div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : filteredInsights.length === 0 && (
            <div className="text-center py-32 bg-white rounded-[3rem] border border-gray-100 shadow-sm">
              <div className="max-w-xs mx-auto">
                <div className="w-16 h-16 bg-gray-50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                  <Clock className="w-8 h-8 text-gray-200" />
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-2">暂无匹配记录</h3>
                <p className="text-sm text-gray-400 mb-8 leading-relaxed">
                  在该筛选条件下未找到任何分析。尝试更换分类或查看其他月份。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-gray-900 rounded-2xl font-black text-sm text-white hover:bg-black transition-all shadow-xl shadow-gray-200"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}

          {/* 已归档见解区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-24 space-y-8">
              <div className="flex items-center justify-between border-t border-dashed border-gray-200 pt-16">
                <div className="flex items-center gap-4">
                  <div className="p-2.5 bg-gray-100 rounded-2xl">
                    <Archive className="w-5 h-5 text-gray-400" />
                  </div>
                  <div>
                    <h3 className="text-lg font-black text-gray-400">已归档历史</h3>
                    <p className="text-[10px] font-bold text-gray-300 uppercase tracking-[0.2em]">已失效的市场分析</p>
                  </div>
                </div>
                <span className="text-[11px] font-black text-gray-400 bg-gray-100 px-3 py-1 rounded-full border border-gray-200">
                  {archivedItems.length} 条归档
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-12 bg-white">
        <div className="max-w-[1600px] mx-auto px-6 text-center">
          <p className="text-[10px] text-gray-300 font-bold uppercase tracking-[0.4em]">个人交易日记 system · 洞察记录与回溯 · 2025</p>
        </div>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle, TrendingUp, TrendingDown, Activity, Quote } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-white/80 text-red-600 border-red-200',
      accent: 'bg-red-50/50 border-red-500 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-white/80 text-green-600 border-green-200',
      accent: 'bg-green-50/50 border-green-500 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-white/80 text-blue-600 border-blue-200',
      accent: 'bg-blue-50/50 border-blue-500 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-white/80 text-gray-500 border-gray-200',
      accent: 'bg-gray-50/50 border-gray-400 text-gray-900',
      icon: <Circle className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-50/40 border-emerald-100 shadow-sm';
      case '已失效': return 'bg-slate-100/40 border-slate-200 shadow-none opacity-80 grayscale-[0.3]';
      default: return 'bg-white border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-sky-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (completionStatus) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-[2rem] p-6 transition-all duration-500 flex flex-col h-full ${getCardStyle()}`}>
      {/* 顶部状态标记 */}
      <div className="absolute -top-3 left-6 flex gap-2">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider shadow-lg transition-all active:scale-90 hover:brightness-110 ${getTagStyle()}`}
          title="点击切换状态"
        >
          {getStatusIcon()}
          {completionStatus}
        </button>
      </div>

      <div className="flex justify-between items-start mb-4 gap-3 pt-2">
        <div className="flex-grow">
          <h3 className="text-2xl font-black text-gray-900 tracking-tight mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1.5 font-bold">
            <Calendar className="w-3 h-3 opacity-60" />
            {date}
          </div>
        </div>
        <div className={`px-3 py-1.5 rounded-xl text-[11px] font-black border flex items-center justify-center gap-2 shrink-0 min-w-[80px] shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="space-y-4 flex-grow">
        {/* 核心观察 */}
        <div className={`p-4 rounded-2xl border transition-colors ${
          completionStatus === '已完成' ? 'bg-white/60 border-emerald-100/50' : completionStatus === '已失效' ? 'bg-white/40 border-slate-100/50' : 'bg-gray-50/50 border-gray-100'
        }`}>
          <div className="flex items-center gap-2 mb-2">
            <div className={`w-1 h-3 rounded-full ${completionStatus === '已完成' ? 'bg-emerald-400' : completionStatus === '已失效' ? 'bg-slate-300' : 'bg-gray-300'}`}></div>
            <p className={`text-[10px] font-black uppercase tracking-widest ${
              completionStatus === '已完成' ? 'text-emerald-500' : completionStatus === '已失效' ? 'text-slate-400' : 'text-gray-400'
            }`}>核心观察</p>
          </div>
          <p className={`text-sm leading-relaxed font-medium line-clamp-4 ${completionStatus === '已失效' ? 'text-slate-500 italic' : 'text-gray-700'}`}>
            {insight.focusPoints}
          </p>
        </div>

        {/* 关键点位 */}
        {insight.keyLevel && (
          <div className={`flex items-center justify-between p-3 px-4 rounded-2xl border border-dashed ${
            completionStatus === '已完成' ? 'bg-emerald-500/5 border-emerald-200' : completionStatus === '已失效' ? 'bg-slate-500/5 border-slate-200' : 'bg-gray-500/5 border-gray-200'
          }`}>
            <p className={`text-[10px] font-black uppercase tracking-widest ${
              completionStatus === '已完成' ? 'text-emerald-600' : completionStatus === '已失效' ? 'text-slate-500' : 'text-gray-500'
            }`}>关键点位</p>
            <p className={`text-lg font-black tracking-tighter ${
              completionStatus === '已完成' ? 'text-emerald-700' : completionStatus === '已失效' ? 'text-slate-700' : 'text-gray-900'
            }`}>{insight.keyLevel}</p>
          </div>
        )}

        {/* 交易策略 - 优化后的无黑色背景设计 */}
        <div className="relative group/strategy">
          <div className={`p-5 rounded-2xl border-l-[6px] transition-all duration-300 ${
            completionStatus === '已失效' 
              ? 'bg-slate-50 border-slate-300' 
              : completionStatus === '已完成'
              ? 'bg-emerald-50/60 border-emerald-400'
              : `${accent}`
          }`}>
            <div className="flex items-center justify-between mb-2">
              <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${
                completionStatus === '已失效' ? 'text-slate-400' : 'opacity-60'
              }`}>交易策略 / Strategy</p>
              <Quote className={`w-3 h-3 rotate-180 opacity-20`} />
            </div>
            <p className={`text-[13px] font-bold leading-relaxed ${
              completionStatus === '已失效' ? 'text-slate-500 italic' : 'text-gray-900'
            }`}>
              {insight.strategy}
            </p>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-5 border-t border-gray-100/60 flex justify-end items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300 transform translate-y-2 group-hover:translate-y-0">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive, Inbox, Search } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('timeline');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  // 生成侧边栏的时间轴归档分组
  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  // 根据当前筛选条件进行初步过滤
  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  // 分离活跃和已归档见解
  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus !== '已失效'),
      archivedItems: filteredInsights.filter(i => i.completionStatus === '已失效')
    };
  }, [filteredInsights]);

  // 对活跃见解进行分组
  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};

    activeItems.forEach(insight => {
      let label = "";
      if (sortMode === 'timeline') {
        const d = new Date(insight.updatedAt);
        label = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
      } else {
        label = insight.category;
      }

      if (!groups[label]) {
        groups[label] = [];
      }
      groups[label].push(insight);
    });

    const entries = Object.entries(groups);
    if (sortMode === 'category') {
      return entries.sort((a, b) => {
        return CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any);
      });
    }
    return entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { 
        ...i, 
        ...data, 
        updatedAt: data.updatedAt || i.updatedAt 
      } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen bg-[#fafafa] flex flex-col selection:bg-red-100 selection:text-red-900">
      <header className="sticky top-0 z-40 bg-white/95 backdrop-blur-2xl border-b border-gray-100 px-8 py-5">
        <div className="max-w-[1600px] mx-auto grid grid-cols-[240px_1fr_240px] items-center">
          {/* 左侧：Logo 和 标题 */}
          <div className="flex items-center gap-4">
            <div className="bg-gray-900 p-3 rounded-[1.25rem] shadow-xl shadow-gray-200 rotate-[-5deg]">
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none mb-1">市场周刊</h1>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Journal Pro</p>
            </div>
          </div>

          {/* 中间：居中且加大的导航栏 */}
          <div className="flex justify-center">
            <nav className="flex items-center bg-gray-100/50 p-1.5 rounded-2xl border border-gray-200/40 gap-1.5 shadow-inner">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-7 py-2.5 rounded-xl text-[14px] font-black transition-all whitespace-nowrap active:scale-90 relative ${
                    activeCategory === cat 
                      ? 'bg-white text-gray-900 shadow-xl shadow-gray-200/50 border border-gray-100' 
                      : 'text-gray-400 hover:text-gray-900 hover:bg-white/40'
                  }`}
                >
                  {cat}
                  {activeCategory === cat && (
                    <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-red-500 rounded-full"></span>
                  )}
                </button>
              ))}
            </nav>
          </div>

          {/* 右侧：操作按钮 */}
          <div className="flex items-center gap-4 justify-end">
            <button className="p-3 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-2xl transition-all active:scale-95">
              <Search className="w-5 h-5" />
            </button>
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-6 py-3 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2.5 shadow-2xl shadow-red-200 font-black text-sm active:scale-95 group"
            >
              <Plus className="w-4 h-4 transition-transform group-hover:rotate-90" />
              <span>新记录</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-12">
        <aside className="lg:w-60 space-y-12 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2.5 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-[12px] font-black text-gray-400 uppercase tracking-[0.2em]">时间轴归档</h3>
            </div>
            <div className="space-y-2">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-5 py-3.5 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                  selectedMonth === null 
                    ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' 
                    : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                }`}
              >
                <span className="flex items-center gap-3">
                  <Hash className={`w-4 h-4 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-5 py-3.5 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                    selectedMonth === month 
                      ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' 
                      : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                  }`}
                >
                  <span className="flex items-center gap-3">
                    <Calendar className={`w-4 h-4 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-8 mb-14">
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <span className="w-8 h-1 bg-red-500 rounded-full"></span>
                <p className="text-[12px] font-black text-red-500 uppercase tracking-[0.3em]">Weekly Insights</p>
              </div>
              <h2 className="text-4xl font-black text-gray-900 tracking-tight italic">
                每一天都有新的洞察。
              </h2>
            </div>

            <div className="flex items-center gap-5">
              <div className="flex bg-gray-100/60 p-1.5 rounded-2xl items-center border border-gray-200/50 shadow-sm">
                <button 
                  onClick={() => setSortMode('timeline')}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[11px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-md border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <CalendarDays className="w-3.5 h-3.5" />
                  时间线
                </button>
                <button 
                  onClick={() => setSortMode('category')}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[11px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-md border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <ListFilter className="w-3.5 h-3.5" />
                  按类别
                </button>
              </div>

              <div className="text-[12px] text-gray-500 font-black bg-white px-5 py-2.5 rounded-2xl border border-gray-100 shadow-lg shadow-gray-100/50">
                共计 <span className="text-gray-900">{filteredInsights.length}</span> 条分析
              </div>
            </div>
          </div>

          {/* 活跃见解区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-20">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-10 h-10 bg-gray-900 rounded-2xl flex items-center justify-center shadow-lg shadow-gray-300">
                  <Inbox className="w-5 h-5 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-gray-900">活跃洞察</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Active Analysis</p>
                </div>
              </div>
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel} className="relative">
                  <div className="flex items-center gap-5 mb-10 sticky top-[120px] z-10 py-4 bg-[#fafafa]/90 backdrop-blur-md">
                    <div className="flex items-center gap-3 px-6 py-2.5 bg-white rounded-2xl border border-gray-200 shadow-xl shadow-gray-100/50">
                      {sortMode === 'timeline' ? <Calendar className="w-4 h-4 text-red-500" /> : <Hash className="w-4 h-4 text-blue-500" />}
                      <span className="text-[13px] font-black text-gray-900 tracking-tight">{groupLabel}</span>
                    </div>
                    <div className="h-[2px] flex-grow bg-gradient-to-r from-gray-200 to-transparent"></div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : filteredInsights.length === 0 && (
            <div className="text-center py-40 bg-white rounded-[4rem] border border-gray-100 shadow-2xl shadow-gray-100">
              <div className="max-w-xs mx-auto">
                <div className="w-20 h-20 bg-gray-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-inner">
                  <Clock className="w-10 h-10 text-gray-200" />
                </div>
                <h3 className="text-2xl font-black text-gray-900 mb-3">空空如也</h3>
                <p className="text-sm text-gray-400 mb-10 leading-relaxed font-medium">
                  该筛选条件下暂时没有记录。是时候记录一笔新的市场观点了。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-3 px-10 py-4 bg-gray-900 rounded-3xl font-black text-sm text-white hover:bg-black transition-all shadow-2xl shadow-gray-300 active:scale-95"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}

          {/* 已归档见解区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-32 space-y-12">
              <div className="flex items-center justify-between border-t-4 border-double border-gray-100 pt-20">
                <div className="flex items-center gap-5">
                  <div className="p-3.5 bg-gray-100 rounded-[1.5rem] shadow-inner">
                    <Archive className="w-6 h-6 text-gray-400" />
                  </div>
                  <div>
                    <h3 className="text-xl font-black text-gray-400">已归档历史</h3>
                    <p className="text-[10px] font-bold text-gray-300 uppercase tracking-[0.3em]">Archived Market Notes</p>
                  </div>
                </div>
                <span className="text-[12px] font-black text-gray-400 bg-gray-50 px-4 py-1.5 rounded-2xl border border-gray-100">
                  {archivedItems.length} 条归档
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-16 bg-white">
        <div className="max-w-[1600px] mx-auto px-8 flex flex-col items-center gap-6">
          <div className="flex items-center gap-3 opacity-30 grayscale">
             <div className="bg-gray-900 p-2 rounded-lg">
                <LayoutGrid className="w-4 h-4 text-white" />
              </div>
              <h1 className="text-lg font-black text-gray-900 tracking-tight leading-none">市场周刊</h1>
          </div>
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.5em]">Trading Journal Pro system · 洞察记录与回溯 · EST. 2025</p>
        </div>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;
